            ICreateSlipInputReturnOrderByCenterFacade createSlipInputReturnOrderByCenterFacade = (ICreateSlipInputReturnOrderByCenterFacade)ClassObjectUtil.GetFacadeInstance("BSFCBYR0601000", typeof(ICreateSlipInputReturnOrderByCenterFacade));

