                    this.ReturnedGoodsSlipEntity.BasicDate,
                    this.ReturnedGoodsSlipEntity.CorporationCode,
                    this.CenterCodeTextBox.Text,
                    storeNameDisclosureDataSet);

                if (storeNameDisclosureDataSet.StoreNameDisclosure.Count == 0)
                {
                    this.ReturnedGoodsSlipEntity.CenterCd = this.CenterCodeTextBox.Text;
                    this.ReturnedGoodsSlipEntity.CenterName = string.Empty;
                    this.CenterName.Text = string.Empty;

                    this.SearchButton.Enabled = false;
                    throw RetailBusinessException.CreateInstance(ErrorKey.ERRCBYRB0185);
                }

                this.SearchButton.Enabled = true;

                this.SetSession("StoreCd", this.ReturnedGoodsSlipEntity.CenterCd);
                this.ReturnedGoodsSlipEntity.CenterCd = this.CenterCodeTextBox.Text;
                this.ReturnedGoodsSlipEntity.CenterName = storeNameDisclosureDataSet.StoreNameDisclosure.First().StoreKanji;
            }

            this.ShowReturnedGoodsSlipEntityData();
        }

