    /// <summary>
    /// 画面 ID [SCRCBYR060601] 返品伝票入力画面から呼び出される Web サービスクラスです。
    /// </summary>
    [WebService(Namespace = WebServicesConstants.CoreCenterNameSpace)]
    [WebServiceBinding(ConformsTo = WsiProfiles.BasicProfile1_1)]
    [System.ComponentModel.ToolboxItem(false)]
    public class PurchaseDataInputForReturnOrderService_CSR : JsonServiceBase
    {
        #region フィールド
        // Facade ID Const ----------------------------------------
        /// <summary>
        /// 返品伝票入力のファサードIDです。
        /// </summary>
        private static readonly string FACADE_ID_RETURN_ORDER = "BSFCBYR0607";

        /// <summary>
        /// AP変数[APVCBYR0003:BYR伝票検索ヘッダ一覧最大行数」のAPVariableCodeです。
        /// </summary>
        private static readonly string BYR_SLIPSEARCH_MAXLINE = "APVCBYR0003";
        #endregion

        #region [WSCBYR0101] セッション情報取得 ---------------------------

        /// <summary>
        /// [WSCBYR0101] セッション情報取得
        /// <remarks>呼び元の画面との受渡し情報を取得します。</remarks>
        /// </summary>
        /// <returns>引渡し情報のオブジェクトです。</returns>
        [WebMethod(EnableSession = true)]
        public JsonResult<SOEFH> GetSessionObjects(EmptyJsonArgument arg)
        {
            // -- 受渡しオブジェクト生成 --
            var sessionObjectEntity = new SOEFH()
            {
                //法人コード
                CC = UserProfile.CorporationCode,
                //バッチ番号
                BN = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_BatchNo")),
                //伝票種別コード
                STC = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SlipTypeCd")),
                //伝票区分
                SD = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SlipDiv")),
                //伝票番号
                SN = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SlipNo")),
                //遷移元画面ID
                BSI = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_BackScreenId")),
                C1C = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_Category1Cd")),
                DF = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SearchDateFrom")),
                DT = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SearchDateTo")),
                //2012/02/25 Orizon MSATO Add Start
                //取引先コード
                SuC = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_SupplierCd")),
                //返品日
                DD = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_DeliveryDate")),
                //店舗コード
                StrC = Convert.ToString(GetSession("PurchaseDataInputForReturnOrder_StoreCd")),
                //2012/02/25 Orizon MSATO Add End
            };

            return new JsonResult<SOEFH>(sessionObjectEntity);
        }

        #endregion

        #region [WSCBYR0102] ページロード時(登録[新規]) -------------------

        /// <summary>
        /// [WSCBYR0102] ページロード時(登録[新規])
        /// <remarks>ページロード時（登録[新規モード])に呼ばれるサービスです。</remarks>
        /// </summary>
        [WebMethod(EnableSession = true)]
        public JsonResult<InitLoadRegisterResultSetForHtml5> InitPageLoadRegisterModeNew(
            JsonArgument<SOEFH> arg)
        {
            var sessionObjectEntity = arg.Value;
            // -- 引数チェック ---
            if (sessionObjectEntity == null)
            {
                throw new ArgumentNullException("sessionObjectEntity");
            }

            // -- 参照オブジェクトの生成 --
            var coverSheetInputStatusSearchEntity = new CoverSheetInputStatusSearchEntity()
            {
                CorporationCode = sessionObjectEntity.CC,
                SlipTypeCd = sessionObjectEntity.STC,
                SlipDiv = sessionObjectEntity.SD,
                BatchNo = sessionObjectEntity.BN,
                SlipNo = sessionObjectEntity.SN,
            };

            InitLoadRegisterResultSetForHtml5 resultSet;

            using (CMCSystemDateDataSet cmcSystemDataSet = new CMCSystemDateDataSet())
            using (SlipInputStatusDataSet slipInputStatusDataSet = new SlipInputStatusDataSet())
            using (BYRSlipTypeMasterDataSet slipTypeMasterDataSet = new BYRSlipTypeMasterDataSet())
            using (BYRSupplierInfoSLDataSet supplierInfoSLDataSet = new BYRSupplierInfoSLDataSet())
            using (BYRStoreInfoSLDataSet storeInfoSLDataSet = new BYRStoreInfoSLDataSet())
            using (BYRCategory1InfoSLDataSet category1InfoSLDataSet = new BYRCategory1InfoSLDataSet())
            {
                string myStoreCode = String.Empty;
                IDictionary<string, string> apVariablesDictionary = new Dictionary<string, string>();

                // -- Facadeの呼び出し --
                var facadeInstance = (IPurchaseDataInputForReturnOrderFacade)
                    ClassObjectUtil.GetFacadeInstance(
                        FACADE_ID_RETURN_ORDER,
                        typeof(IPurchaseDataInputForReturnOrderFacade));

                // -- 設定情報の読込み --
                facadeInstance.InitPageLoadRegisterModeNew(
                    coverSheetInputStatusSearchEntity,
                    apVariablesDictionary,
                    cmcSystemDataSet,
                    slipInputStatusDataSet,
                    slipTypeMasterDataSet,
                    supplierInfoSLDataSet,
                    storeInfoSLDataSet,
                    category1InfoSLDataSet,
                    out myStoreCode);

                // -- 結果セットの生成 --
                resultSet = new InitLoadRegisterResultSetForHtml5()
                {
                    CoverSheetInputStatusSearchEntity = coverSheetInputStatusSearchEntity,
                };

                /* USOLV ADD 2022/06/21 START */
                IDictionary<string, string> apVariablesDetailDictionary = new Dictionary<string, string>();
                apVariablesDetailDictionary = APVariableUtil.GetAPVariableDetailedList(APVariableDetailedListKey.BYR_DEFAULT_TRANSFER_DATE, coverSheetInputStatusSearchEntity.CorporationCode);

                // デフォルト譲渡日
                IList<CodeDivisionValueElement> codeDivisionList = new List<CodeDivisionValueElement>();
                codeDivisionList = CodeDivisionUtil.GetCodeDivisionValueElements(CodeDivisionKey.TaxExemptionBusinessDiv, coverSheetInputStatusSearchEntity.CorporationCode);
                resultSet.CodeDivisionList = 
                    (from dt in codeDivisionList
                     select new CVE { C = dt.CodeDivisionValue, V = dt.CodeDivisionValueName })
                    .ToList();
                SetSession("CodeDivisionList", resultSet.CodeDivisionList);
                /* USOLV ADD 2022/06/21 END */

                // -- 対象項目の抽出・変換 --
                // 取引先
                resultSet.SupplierList =
                    (from dt in supplierInfoSLDataSet.SupplierInfoSL
                     select new CVE { C = dt.SupplierCd, V = dt.SupplierKanji })
                    .ToList();

                // 店舗
                resultSet.StoreList = new List<CVE>();
                if (apVariablesDictionary.ContainsKey(APVariableListKey.BYR_FIXED_STORE_ID))
                {
                    // 店舗を固定にするかどうかをチェックします。
                    string fixedStore = apVariablesDictionary[APVariableListKey.BYR_FIXED_STORE_ID];
                    if (!String.IsNullOrEmpty(fixedStore) && fixedStore == "1" && !String.IsNullOrEmpty(myStoreCode))
                    {
                        // 固定の場合時店舗のみを返します。
                        BYRStoreInfoSLDataSet.StoreInfoSLDataTableRow row = storeInfoSLDataSet.StoreInfoSLDataTable.Where(o => o["StoreCd"].ToString() == myStoreCode).FirstOrDefault();
                        if (row != null)
                        {
                            resultSet.StoreList.Add(new CVE { C = row.StoreCd, V = row.StoreKanji });
                        }
                    }
                    else
                    {
                        resultSet.StoreList.AddRange((from dt in storeInfoSLDataSet.StoreInfoSLDataTable
                                                      select new CVE { C = dt.StoreCd, V = dt.StoreKanji })
                                            .ToList());
                    }
                }
                else
                {
                    resultSet.StoreList.AddRange((from dt in storeInfoSLDataSet.StoreInfoSLDataTable
                                                  select new CVE { C = dt.StoreCd, V = dt.StoreKanji })
                                        .ToList());
                }


                /* FC-EDIT-START 2019/05/13 何 デプロイ対応：店舗ユーザ対応 */
                ///* FC-EDIT-START 2019/02/21 kikuchi デプロイ対応：店舗ユーザ対応 */
                ////店舗ユーザの場合、戻り値に自店舗コードをセットする。
                //if (!string.IsNullOrEmpty(myStoreCode))
                //{
                //    resultSet.MyStoreCd = myStoreCode;
